const item = $input.first().json;
const body = item.body || item;
const msg = body.message || {};
const call = (msg.toolCallList && msg.toolCallList[0]) || {};
// Mock handoff: in production this would be a warm transfer (SIP/Twilio) or a callback ticket in a CRM.
const result = { status: 'handoff_requested', message: 'A claims representative has been notified and will call the customer back shortly.' };
return [{ json: { response: { results: [{ toolCallId: call.id || 'manual-test', result: JSON.stringify(result) }] } } }];
